code:
  language: csharp
  harness: statements
  source: |
    using System.Threading.Channels;

    // Test: the consumer must process a published order message.
    var channel = Channel.CreateUnbounded<string>();
    var consumer = new OrderConsumer(channel.Reader);
    _ = Task.Run(() => consumer.RunAsync());

    await channel.Writer.WriteAsync("order:42");
    await WaitUntil(() => consumer.ProcessedCount == 1, TimeSpan.FromMilliseconds(500));
    Console.WriteLine("PASS");

    static async Task WaitUntil(Func<bool> condition, TimeSpan timeout)
    {
        DateTime deadline = DateTime.UtcNow + timeout;
        while (!condition())
        {
            if (DateTime.UtcNow >= deadline)
            {
                return;
            }
            await Task.Delay(20);
        }
    }

    class OrderConsumer
    {
        private readonly ChannelReader<string> _reader;
        private int _processed;

        public OrderConsumer(ChannelReader<string> reader) => _reader = reader;

        public int ProcessedCount => Volatile.Read(ref _processed);

        public async Task RunAsync()
        {
            await foreach (string message in _reader.ReadAllAsync())
            {
                if (message.StartsWith("orders:", StringComparison.Ordinal))
                {
                    Interlocked.Increment(ref _processed);
                }
            }
        }
    }
